-- =============================================================================
-- 519 — LE CAHIER D'EXERCICES DE 1RE (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 519 --niveau 1re --fichiers biotechnologies.n2,droit-economie.n1,droit-economie.n2 --suffixe 7 > supabase/contenu/519_exercices_1re_7.sql
--
-- 72 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   biotechnologies.n2      24 exercices · 8 chapitres
--   droit-economie.n1       24 exercices · 8 chapitres
--   droit-economie.n2       24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('61621029-3b3b-521a-a0e8-14c4f42020e7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quelle gélose pour quel travail ?","competence":"lire-tableau","situation":"Au laboratoire du lycée, Inès sort quatre milieux du réfrigérateur pour le TP de microbiologie. Chaque flacon porte une étiquette qui liste ses ingrédients caractéristiques.","documents":[{"id":"milieux","type":"tableau","titre":"Les étiquettes des quatre milieux","colonnes":["Milieu","Ingrédients caractéristiques"],"lignes":[["A","peptones, extrait de viande, agar"],["B","peptones, agar, sels biliaires, cristal violet"],["C","peptones, agar, lactose, rouge neutre (indicateur de pH)"],["D","peptones, extrait de viande (sans agar)"]],"enteteLignes":true,"source":"Compositions simplifiées, écrites pour l’exercice"}],"questions":[{"enonce":"Touche la case qui contient des agents inhibiteurs, ces substances qui empêchent certaines bactéries de pousser.","aide":"Cherche des sels biliaires ou un colorant comme le cristal violet.","type":"zone","document":"milieux","multiple":false},{"enonce":"Parmi ces quatre milieux, combien sont des milieux solides (gélosés) sur lesquels on peut obtenir des colonies ?","aide":"C’est l’agar qui donne la gélose : repère les lignes où il figure.","type":"nombre"},{"enonce":"Associe chaque milieu à son rôle.","aide":"Un substrat fermentescible et un indicateur de pH signent le milieu d’orientation.","type":"association","gauche":[{"id":"g0","texte":"Milieu A"},{"id":"g1","texte":"Milieu B"},{"id":"g2","texte":"Milieu C"}],"droite":[{"id":"d0","texte":"Sélectif : ne laisser pousser qu’un groupe"},{"id":"d1","texte":"D’orientation : distinguer par la fermentation du lactose"},{"id":"d2","texte":"Ordinaire : faire pousser la plupart des bactéries"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Les **sels biliaires et le cristal violet** du milieu B freinent certains groupes de bactéries : c’est ce qui fait de B un milieu sélectif."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"A, B et C contiennent de l’agar : **3 milieux** solides. Le milieu D, sans agar, reste liquide : c’est un bouillon."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"A : composition simple, **ordinaire**. B : inhibiteurs, **sélectif**. C : lactose + indicateur de pH, **d’orientation**."}]$ex$::jsonb),
  ('61621029-3b3b-521a-a0e8-14c4f42020e7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Isoler une colonie par stries","competence":"experimenter","situation":"Karim doit obtenir des colonies bien séparées à partir d’un tube de culture trouble. Il réalise un isolement par la méthode des quadrants, puis photographie sa boîte.","documents":[{"id":"boite","type":"schema","titre":"La boîte de Karim","largeur":320,"hauteur":224,"elements":[{"forme":"cercle","cx":160,"cy":105,"r":85,"teinte":"gris","motif":"clair"},{"forme":"ligne","de":[160,28],"a":[160,182],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[82,105],"a":[238,105],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[110,60],"a":[154,60],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[110,68],"a":[154,68],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[110,76],"a":[154,76],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[110,84],"a":[154,84],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[110,92],"a":[154,92],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,62],"a":[208,62],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,74],"a":[208,74],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,86],"a":[208,86],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,98],"a":[208,98],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,114],"a":[208,114],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,128],"a":[208,128],"teinte":"encre","epaisseur":1},{"forme":"ligne","de":[168,142],"a":[208,142],"teinte":"encre","epaisseur":1},{"forme":"cercle","cx":115,"cy":130,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":135,"cy":122,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":125,"cy":150,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":146,"cy":140,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":108,"cy":154,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":140,"cy":160,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":120,"cy":112,"r":3.5,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":36,"cy":34,"r":13,"teinte":"violet","motif":"clair","texte":"A","id":"z1","zone":true},{"forme":"cercle","cx":284,"cy":34,"r":13,"teinte":"violet","motif":"clair","texte":"B","id":"z2","zone":true},{"forme":"cercle","cx":284,"cy":176,"r":13,"teinte":"violet","motif":"clair","texte":"C","id":"z3","zone":true},{"forme":"cercle","cx":36,"cy":176,"r":13,"teinte":"violet","motif":"clair","texte":"D","id":"z4","zone":true},{"forme":"texte","x":160,"y":208,"texte":"Boîte vue de dessus, après isolement","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche la lettre du quadrant où l’on peut prélever une colonie bien isolée.","aide":"Cherche le quadrant où les cellules sont assez éloignées pour donner des colonies séparées.","type":"zone","document":"boite","multiple":false},{"enonce":"Remets dans l’ordre les gestes de Karim, de l’étiquetage à l’incubation.","aide":"On identifie la boîte avant d’y toucher ; on incube en dernier.","type":"ordre","items":[{"id":"a","texte":"Placer la boîte retournée à l’étuve"},{"id":"b","texte":"Prélever l’inoculum avec une anse stérile"},{"id":"c","texte":"Strier le premier quadrant"},{"id":"d","texte":"Inscrire nom, date, milieu et souche sur le fond de la boîte"},{"id":"e","texte":"Strier les quadrants suivants pour diluer peu à peu l’inoculum"}]},{"enonce":"Complète le compte rendu de Karim.","aide":"Plus on strie loin, moins il y a de cellules par endroit.","type":"trous","segments":["L’anse ",0," progressivement l’inoculum d’un quadrant à l’autre : dans le dernier, chaque cellule isolée donne une ",1," ."],"banque":["concentre","dilue","colonie","toxine"]},{"enonce":"Karim a écrit son nom sur le couvercle. Pourquoi est-ce une erreur de traçabilité ?","aide":"Pense à ce qui arrive quand on empile et ouvre plusieurs boîtes.","type":"choix","options":[{"id":"a","texte":"On n’inscrit jamais de nom sur une boîte de Petri"},{"id":"b","texte":"Le couvercle peut être échangé avec celui d’une autre boîte"},{"id":"c","texte":"Le feutre risque d’abîmer la gélose pendant l’incubation"},{"id":"d","texte":"Le couvercle empêche la boîte d’être placée à l’étuve"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Le quadrant **D** est le dernier strié : l’inoculum y est assez dilué pour que chaque cellule isolée forme sa propre colonie."},{"cle":{"type":"ordre","ids":["d","b","c","e","a"]},"explication":"On **étiquette d’abord** (traçabilité), on prélève, on strie le premier quadrant puis les suivants, et on **incube retournée** pour que la condensation ne tombe pas sur la gélose."},{"cle":{"type":"trous","trous":[["dilue"],["colonie"]]},"affichage":"dilue · colonie","explication":"L’anse **dilue** l’inoculum de quadrant en quadrant ; chaque cellule isolée du dernier donne une **colonie**."},{"cle":{"type":"choix","ids":["b"]},"explication":"On écrit **sur le fond** : un couvercle se déplace d’une boîte à l’autre, et l’identification serait alors fausse."}]$ex$::jsonb),
  ('61621029-3b3b-521a-a0e8-14c4f42020e7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un fromage blanc sur deux géloses","competence":"analyser-document","situation":"Mathilde contrôle un fromage blanc. Elle en ensemence le même volume sur une gélose ordinaire et sur une gélose sélective des bactéries Gram négatif, lactosée avec un indicateur de pH qui vire au jaune quand le milieu s’acidifie. Voici les deux boîtes après incubation.","documents":[{"id":"boites","type":"schema","titre":"Les deux boîtes après 24 h à 37 °C","largeur":320,"hauteur":214,"elements":[{"forme":"cercle","cx":85,"cy":100,"r":68,"teinte":"gris","motif":"clair"},{"forme":"cercle","cx":58,"cy":68,"r":9,"teinte":"sable","motif":"plein"},{"forme":"cercle","cx":108,"cy":62,"r":9,"teinte":"sable","motif":"plein"},{"forme":"cercle","cx":70,"cy":128,"r":9,"teinte":"sable","motif":"plein"},{"forme":"cercle","cx":112,"cy":118,"r":9,"teinte":"sable","motif":"plein"},{"forme":"cercle","cx":88,"cy":92,"r":4,"teinte":"blanc","motif":"plein"},{"forme":"cercle","cx":50,"cy":100,"r":4,"teinte":"blanc","motif":"plein"},{"forme":"cercle","cx":100,"cy":144,"r":4,"teinte":"blanc","motif":"plein"},{"forme":"cercle","cx":78,"cy":74,"r":4,"teinte":"blanc","motif":"plein"},{"forme":"cercle","cx":62,"cy":100,"r":7,"teinte":"rose","motif":"plein"},{"forme":"cercle","cx":235,"cy":100,"r":68,"teinte":"gris","motif":"clair"},{"forme":"cercle","cx":212,"cy":78,"r":20,"teinte":"jaune","motif":"clair"},{"forme":"cercle","cx":240,"cy":112,"r":20,"teinte":"jaune","motif":"clair"},{"forme":"cercle","cx":212,"cy":78,"r":8,"teinte":"ambre","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":258,"cy":72,"r":8,"teinte":"ambre","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":240,"cy":112,"r":8,"teinte":"ambre","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":205,"cy":134,"r":8,"teinte":"ambre","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":266,"cy":140,"r":8,"teinte":"ambre","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":85,"y":186,"texte":"Gélose ordinaire","taille":"petit","gras":true},{"forme":"texte","x":235,"y":186,"texte":"Gélose sélective lactosée","taille":"petit","gras":true},{"forme":"texte","x":235,"y":200,"texte":"avec indicateur de pH","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche les colonies de la gélose sélective qui sont entourées d’un virage de couleur.","aide":"Le virage est une auréole autour de la colonie : il y en a deux.","type":"zone","document":"boites","multiple":true},{"enonce":"Combien de colonies de plus la gélose ordinaire compte-t-elle par rapport à la gélose sélective ?","aide":"Compte les colonies de chaque boîte, puis fais la différence.","type":"nombre"},{"enonce":"Pourquoi la gélose sélective porte-t-elle moins de colonies ?","aide":"Qu’est-ce qui distingue un milieu sélectif d’un milieu ordinaire ?","type":"choix","options":[{"id":"a","texte":"Elle ne contient aucune source de carbone organique"},{"id":"b","texte":"Elle a été incubée moins longtemps que l’autre boîte"},{"id":"c","texte":"Ses agents inhibiteurs bloquent certains groupes de bactéries"},{"id":"d","texte":"Elle contient moins d’eau que la gélose ordinaire"}],"multiple":false},{"enonce":"Les colonies sans auréole de la gélose sélective sont…","aide":"Elles ont poussé sur un milieu qui laisse passer un seul groupe, mais sans acidifier.","type":"choix","options":[{"id":"a","texte":"Gram négatif, lactose négatif"},{"id":"b","texte":"Des levures qui fermentent le lactose"},{"id":"c","texte":"Gram positif, lactose négatif"},{"id":"d","texte":"Gram positif, lactose positif"}],"multiple":false},{"enonce":"Écris la conclusion pour les colonies entourées d’une auréole.","aide":"Reprends ce que le milieu sélectionne, puis ce que l’auréole révèle.","type":"trous","segments":["Ce sont des bactéries Gram ",0," , lactose ",1," ."],"banque":["positif","anaérobie","inhibé","négatif"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3"]},"explication":"Les colonies entourées d’une auréole sont celles qui **fermentent le lactose** : elles acidifient le milieu et font virer l’indicateur de pH."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Gélose ordinaire : 9 colonies. Gélose sélective : 5. L’écart est de **4 colonies**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un milieu sélectif contient des **agents inhibiteurs** : seules les bactéries capables de leur résister forment des colonies."},{"cle":{"type":"choix","ids":["a"]},"explication":"Elles ont poussé sur un milieu réservé aux **Gram négatif** et n’ont pas acidifié le milieu : elles ne fermentent pas le lactose."},{"cle":{"type":"trous","trous":[["negatif"],["positif"]]},"affichage":"négatif · positif","explication":"Gram **négatif** (le milieu ne laisse pousser qu’elles) et lactose **positif** (elles acidifient le milieu autour d’elles)."}]$ex$::jsonb),
  ('2517347d-cfb3-5c19-b997-a697c246a579'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le registre des souches du laboratoire","competence":"lire-tableau","situation":"Sarah recopie dans le registre du laboratoire le nom de trois souches bactériennes conservées au réfrigérateur. Elle les range par genre, espèce et famille.","documents":[{"id":"registre","type":"tableau","titre":"Le registre des souches","colonnes":["Genre","Espèce","Famille"],"lignes":[["Escherichia","coli","Enterobacteriaceae"],["Staphylococcus","aureus","Staphylococcaceae"],["Bacillus","subtilis","Bacillaceae"]],"enteteLignes":false,"source":"Registre écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui contient l’espèce de la bactérie du genre Bacillus.","aide":"L’espèce est le deuxième mot du nom binomial, en minuscule.","type":"zone","document":"registre","multiple":false},{"enonce":"Après une première mention, comment abrège-t-on *Escherichia coli* ?","aide":"On garde l’initiale du genre suivie d’un point, puis l’espèce.","type":"texte","placeholder":"Écris l’abréviation"},{"enonce":"Associe chaque niveau de classification à l’exemple du registre.","aide":"Le nom d’une famille se termine par -aceae ; une espèce porte deux mots.","type":"association","gauche":[{"id":"g0","texte":"Famille"},{"id":"g1","texte":"Genre"},{"id":"g2","texte":"Espèce"}],"droite":[{"id":"d0","texte":"Escherichia coli"},{"id":"d1","texte":"Escherichia"},{"id":"d2","texte":"Enterobacteriaceae"}]}]}$ex$::jsonb,
