  ('2517347d-cfb3-5c19-b997-a697c246a579'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui vit dans le kéfir ?","competence":"analyser-document","situation":"Au club sciences, Élodie prépare un état frais de kéfir de fruits. Elle observe cinq types de cellules, les schématise à l’échelle et note leurs caractères dans un tableau. Elle veut savoir lesquelles sont des levures et lesquelles des bactéries.","documents":[{"id":"etat","type":"schema","titre":"L’état frais de kéfir","largeur":320,"hauteur":214,"elements":[{"forme":"cercle","cx":94,"cy":52,"r":9,"teinte":"ambre","motif":"plein"},{"forme":"ellipse","cx":60,"cy":65,"rx":28,"ry":20,"teinte":"ambre","motif":"plein","id":"z1","zone":true},{"forme":"ellipse","cx":200,"cy":62,"rx":36,"ry":22,"teinte":"ambre","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":50,"cy":140,"r":4,"teinte":"ambre","motif":"plein","id":"z3","zone":true},{"forme":"ellipse","cx":120,"cy":140,"rx":12,"ry":4,"teinte":"ambre","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":258,"cy":126,"r":9,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":232,"cy":142,"r":24,"teinte":"ambre","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":60,"y":96,"texte":"a","gras":true},{"forme":"texte","x":200,"y":96,"texte":"c","gras":true},{"forme":"texte","x":50,"y":160,"texte":"b","gras":true},{"forme":"texte","x":120,"y":160,"texte":"d","gras":true},{"forme":"texte","x":232,"y":176,"texte":"e","gras":true},{"forme":"ligne","de":[20,202],"a":[100,202],"teinte":"encre"},{"forme":"ligne","de":[20,197],"a":[20,207],"teinte":"encre"},{"forme":"ligne","de":[100,197],"a":[100,207],"teinte":"encre"},{"forme":"texte","x":130,"y":206,"texte":"= 10 µm","taille":"petit","ancre":"debut"}],"source":"Schéma à l’échelle écrit pour l’exercice"},{"id":"mesures","type":"tableau","titre":"Les caractères relevés","colonnes":["Cellule","Forme","Taille","Bourgeon"],"lignes":[["a","ovale","7 µm","oui"],["b","ronde","1 µm","non"],["c","ovale","9 µm","non"],["d","bâtonnet","3 µm","non"],["e","ronde","6 µm","oui"]],"enteteLignes":true,"source":"Mesures inventées pour l’exercice"}],"questions":[{"enonce":"Touche les cellules du schéma qui portent un bourgeon.","aide":"Un bourgeon est une petite cellule fille accolée à la grande.","type":"zone","document":"etat","multiple":true},{"enonce":"Classe chaque cellule en levure ou en bactérie à l’aide du tableau.","aide":"Compare la taille à 5-10 µm pour une levure et à environ 1 µm pour une bactérie en forme de coque.","type":"categories","categories":[{"id":"c0","texte":"Levure"},{"id":"c1","texte":"Bactérie"}],"items":[{"id":"i0","texte":"Cellule e"},{"id":"i1","texte":"Cellule a"},{"id":"i2","texte":"Cellule d"},{"id":"i3","texte":"Cellule c"},{"id":"i4","texte":"Cellule b"}]},{"enonce":"Combien de fois la cellule c est-elle plus longue que la cellule b ?","aide":"Divise les deux tailles du tableau.","type":"nombre"},{"enonce":"Que conclut Élodie sur son kéfir ?","aide":"Les deux classes du tableau sont-elles représentées ?","type":"choix","options":[{"id":"a","texte":"Il contient à la fois des levures et des bactéries"},{"id":"b","texte":"Il ne contient que des levures"},{"id":"c","texte":"Il ne contient que des bactéries"},{"id":"d","texte":"Il ne contient que des champignons filamenteux"}],"multiple":false},{"enonce":"Élodie veut nommer l’espèce du bacille d. Que peut-elle dire à partir de la morphologie seule ?","aide":"Deux bacilles très différents peuvent se ressembler au microscope.","type":"choix","options":[{"id":"a","texte":"Le genre Staphylococcus, grâce à la petite taille"},{"id":"b","texte":"Seulement que c’est un bacille ; il faut d’autres caractères"},{"id":"c","texte":"L’espèce exacte, grâce à la taille de 3 µm mesurée"},{"id":"d","texte":"L’espèce exacte, grâce à la forme en bâtonnet observée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z5"]},"explication":"Les cellules **a** et **e** portent un bourgeon : c’est un caractère de levure, jamais observé chez une bactérie."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Levures : a, c et e (ovales ou rondes, 6 à 9 µm, bourgeon pour a et e). Bactéries : b (coque de 1 µm) et d (**bacille** de 3 µm)."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"9 µm ÷ 1 µm = **9** : une levure est beaucoup plus grosse qu’une coque."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le kéfir contient des **levures** (a, c, e) et des **bactéries** (b, d), comme l’état frais de levain décrit dans le cours."},{"cle":{"type":"choix","ids":["b"]},"explication":"La morphologie permet d’**orienter**, pas de nommer l’espèce : il faut compléter par des caractères culturaux et métaboliques."}]$ex$::jsonb),
  ('c9b7b27a-1d15-566e-9f8b-63615d8bad6d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois tubes pour diluer un yaourt","competence":"calculer","situation":"Noé prépare les dilutions d’un yaourt avant le dénombrement : il pèse 10 g de produit dans 90 mL de diluant, puis enchaîne trois tubes contenant chacun 9 mL de diluant.","documents":[{"id":"serie","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Mère 10⁻¹"},{"id":"z2","texte":"Tube 1"},{"id":"z3","texte":"Tube 2"},{"id":"z4","texte":"Tube 3"}],"liens":[{"de":"z1","a":"z2","texte":"1 mL"},{"de":"z2","a":"z3","texte":"1 mL"},{"de":"z3","a":"z4","texte":"1 mL"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le tube dont la dilution est 10⁻³.","aide":"À chaque tube, la dilution est divisée par 10 : la mère est à 10⁻¹, le tube 1 à 10⁻².","type":"zone","document":"serie","multiple":false},{"enonce":"La dilution du tube 3 s’écrit 10⁻ⁿ. Quelle est la valeur de n ?","aide":"Compte combien de fois on a dilué au 1/10 depuis le produit pur, mère comprise.","type":"nombre"},{"enonce":"Quel volume total de diluant a-t-on versé dans les trois tubes (sans compter les 90 mL de la mère) ?","aide":"Trois tubes, chacun avec 9 mL.","type":"nombre","unite":"mL"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Mère 10⁻¹, tube 1 : 10⁻², tube 2 : **10⁻³**, tube 3 : 10⁻⁴. À chaque passage, 1 mL dans 9 mL divise par 10."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"La mère est au 1/10 (n = 1), puis chaque tube ajoute une dilution décimale : le tube 3 est à 10⁻⁴, donc **n = 4**."},{"cle":{"type":"nombre","valeur":27,"tolerance":0},"affichage":"27 mL","explication":"3 × 9 mL = **27 mL** de diluant : chaque tube reçoit 9 mL de diluant et 1 mL de la dilution précédente, soit 10 mL."}]$ex$::jsonb),
  ('c9b7b27a-1d15-566e-9f8b-63615d8bad6d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien de levures dans le jus ?","competence":"calculer","situation":"Une brasserie artisanale contrôle la quantité de levures dans un moût en fermentation. Zoé dilue 1 mL de moût dans 99 mL d’eau, remplit une cellule de Malassez et compte les levures dans cinq rectangles. Un rectangle représente un volume de 10⁻⁵ mL.","documents":[{"id":"comptage","type":"tableau","titre":"Levures comptées par rectangle","colonnes":["Rectangle","1","2","3","4","5"],"lignes":[["Levures comptées",17,22,21,19,21]],"enteteLignes":true,"source":"Comptages inventés pour l’exercice"}],"questions":[{"enonce":"Touche le rectangle dont le comptage s’écarte le plus de la moyenne.","aide":"Calcule d’abord la moyenne, puis cherche l’écart le plus grand.","type":"zone","document":"comptage","multiple":false},{"enonce":"Quelle est la moyenne des cinq comptages ?","aide":"Additionne les cinq valeurs puis divise par 5.","type":"nombre","unite":"levures"},{"enonce":"Quelle est la concentration de la suspension diluée, en millions de cellules par mL ?","aide":"Divise la moyenne par le volume d’un rectangle, 10⁻⁵ mL.","type":"nombre","unite":"millions/mL"},{"enonce":"Le moût a été dilué 100 fois. Quelle est sa concentration, en millions de cellules par mL ?","aide":"Il faut multiplier par l’inverse de la dilution.","type":"nombre","unite":"millions/mL"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La moyenne vaut 20. Le rectangle 1 (17) s’écarte de **3**, les autres de 2 au plus : c’est le plus éloigné."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 levures","explication":"(17 + 22 + 21 + 19 + 21) ÷ 5 = 100 ÷ 5 = **20 levures** par rectangle."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 millions/mL","explication":"20 ÷ 10⁻⁵ mL = 2 × 10⁶ cellules par mL, soit **2 millions** de cellules par mL."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 millions/mL","explication":"La suspension a été diluée 100 fois : 2 millions × 100 = **200 millions** de cellules par mL, soit 2 × 10⁸."}]$ex$::jsonb),
  ('c9b7b27a-1d15-566e-9f8b-63615d8bad6d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le fromage frais est-il conforme ?","competence":"resoudre","situation":"Sofiane contrôle un fromage frais. Il met 10 g de produit dans 90 mL de diluant (mère à 10⁻¹), prépare des dilutions décimales et ensemence 1 mL de chaque dilution en profondeur. Il compte les colonies après incubation, puis compare au critère de l’entreprise.","documents":[{"id":"boites","type":"tableau","titre":"Résultats après incubation","colonnes":["Dilution ensemencée","Volume","Colonies comptées"],"lignes":[["10⁻³","1 mL",410],["10⁻⁴","1 mL",148],["10⁻⁵","1 mL",9]],"enteteLignes":true,"source":"Comptages inventés pour l’exercice"},{"id":"critere","type":"fiche","modele":"etiquette","entete":"Critère maison","sousTitre":"Fromage frais","emoji":"🧀","lignes":[{"texte":"Germes revivifiables à 30 °C","valeur":"≤ 1,0 × 10⁶ UFC par g","gras":true},{"separateur":true},{"texte":"Boîtes exploitables","valeur":"15 à 300 colonies"}],"pied":"Critère inventé pour l’exercice"}],"questions":[{"enonce":"Touche le nombre de colonies de la seule boîte exploitable pour le calcul.","aide":"Compare chaque nombre à l’intervalle donné par la fiche : 15 à 300.","type":"zone","document":"boites","multiple":false},{"enonce":"Calcule la concentration du fromage, en milliers d’UFC par gramme (arrondie à deux chiffres significatifs).","aide":"N = n / (V × d), avec n = 148, V = 1 mL et d = 10⁻⁴.","type":"nombre","unite":"milliers UFC/g"},{"enonce":"Que conclut Sofiane en comparant ce résultat au critère ?","aide":"Compare la concentration calculée au seuil maximal, pas le nombre de colonies.","type":"choix","options":[{"id":"a","texte":"Impossible de conclure sans refaire une numération directe"},{"id":"b","texte":"Conforme : le résultat est proche du critère de 10⁶"},{"id":"c","texte":"Non conforme : 1,5 × 10⁶ dépasse le seuil de 1,0 × 10⁶"},{"id":"d","texte":"Conforme : 148 colonies, c’est moins que 300 colonies"}],"multiple":false},{"enonce":"Sofiane recommence avec 0,1 mL de la dilution 10⁻³ et compte 130 colonies. Quelle concentration trouve-t-il, en milliers d’UFC par gramme ?","aide":"Le volume ensemencé a changé : V = 0,1 mL.","type":"nombre","unite":"milliers UFC/g"},{"enonce":"Remets dans l’ordre les étapes du dénombrement après culture.","aide":"On ne compte qu’après l’incubation, et on calcule en dernier.","type":"ordre","items":[{"id":"a","texte":"Réaliser les dilutions décimales en série"},{"id":"b","texte":"Ensemencer un volume exact de plusieurs dilutions"},{"id":"c","texte":"Incuber puis compter les boîtes exploitables"},{"id":"d","texte":"Préparer la suspension mère (10 g + 90 mL)"},{"id":"e","texte":"Calculer N = n / (V × d)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"410 est trop chargé (colonies confluentes), 9 trop pauvre : seule la boîte à **148** colonies convient."},{"cle":{"type":"nombre","valeur":1500,"tolerance":25},"affichage":"1500 milliers UFC/g","explication":"N = 148 / (1 × 10⁻⁴) = 1,48 × 10⁶ ≈ 1,5 × 10⁶ UFC par g, soit **1 500 milliers** d’UFC par gramme."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il faut comparer les **UFC par gramme** au seuil : 1,5 × 10⁶ est supérieur à 1,0 × 10⁶, donc le produit est **non conforme**."},{"cle":{"type":"nombre","valeur":1300,"tolerance":0},"affichage":"1300 milliers UFC/g","explication":"N = 130 / (0,1 × 10⁻³) = 1,3 × 10⁶ UFC par g, soit **1 300 milliers** : du même ordre que le premier essai, ce qui confirme le résultat."},{"cle":{"type":"ordre","ids":["d","a","b","c","e"]},"explication":"Suspension mère → dilutions → ensemencement → incubation et comptage → **calcul** du nombre d’UFC par gramme."}]$ex$::jsonb),
