","texte":"Coupelle non rincée"},{"id":"g1","texte":"Pas d’homogénéisation"},{"id":"g2","texte":"Trait de jauge dépassé"}],"droite":[{"id":"d0","texte":"Concentration différente selon l’endroit"},{"id":"d1","texte":"Concentration trop faible"},{"id":"d2","texte":"Solution à refaire"}]}]}$ex$::jsonb,
