   $ex${"titre":"Une colonne qui retient les acides aminés","competence":"analyser-document","situation":"Pour récupérer l’acide glutamique d’un mélange, Chloé utilise une colonne d’échange d’ions dont la résine est chargée positivement. Elle recueille des fractions de 2 mL et mesure l’intensité de la couleur violette obtenue avec la ninhydrine, d’abord pendant le lavage (fractions 1 à 4), puis pendant l’élution (fractions 5 à 8).","documents":[{"id":"charges","type":"tableau","titre":"Charge à pH 7","colonnes":["Acide aminé","Charge à pH 7"],"lignes":[["Lysine","positive"],["Glycine","neutre"],["Acide glutamique","négative"]],"enteteLignes":true,"source":"Données simplifiées, écrites pour l’exercice"},{"id":"fractions","type":"graphique","forme":"barres","titre":"Intensité de la couleur selon la fraction","categories":["1","2","3","4","5","6","7","8"],"series":[{"nom":"Absorbance","valeurs":[0.05,0.8,0.45,0.04,0.03,0.7,0.3,0.02],"teinte":"violet"}],"axeY":{"titre":"Absorbance","unite":"sans unité","min":0,"max":1,"pas":0.2},"axeX":{"titre":"Numéro de fraction"},"valeurs":false,"source":"Valeurs inventées pour l’exercice"}],"questions":[{"enonce":"Quel acide aminé la résine chargée positivement retient-elle à pH 7 ?","aide":"Des liaisons ioniques se forment avec les molécules de charge opposée.","type":"choix","options":[{"id":"a","texte":"L’acide glutamique"},{"id":"b","texte":"La lysine"},{"id":"c","texte":"La glycine"},{"id":"d","texte":"Aucun des trois"}],"multiple":false},{"enonce":"Touche les deux fractions d’élution qui contiennent l’acide glutamique.","aide":"L’élution commence à la fraction 5 : cherche les barres hautes après le lavage.","type":"zone","document":"fractions","multiple":true},{"enonce":"Remets dans l’ordre les étapes de la séparation.","aide":"On ne détache les molécules fixées qu’après avoir éliminé le reste.","type":"ordre","items":[{"id":"a","texte":"Éluer en changeant le pH ou la concentration en sel"},{"id":"b","texte":"Laver pour éliminer ce qui n’est pas fixé"},{"id":"c","texte":"Déposer le mélange : les molécules de charge opposée se fixent"},{"id":"d","texte":"Repérer chaque fraction par un dépôt révélé à la ninhydrine"}]},{"enonce":"Où trouve-t-on chaque acide aminé : dans le lavage ou dans l’élution ?","aide":"Ce qui n’est pas retenu par la résine sort avec le lavage.","type":"categories","categories":[{"id":"c0","texte":"Fractions de lavage"},{"id":"c1","texte":"Fractions d’élution"}],"items":[{"id":"i0","texte":"Glycine"},{"id":"i1","texte":"Acide glutamique"},{"id":"i2","texte":"Lysine"}]},{"enonce":"Quelle conclusion tire-t-on de l’absence de couleur dans la fraction 4 ?","aide":"La fraction 4 est la dernière du lavage.","type":"choix","options":[{"id":"a","texte":"L’élution a déjà commencé à la fraction 4"},{"id":"b","texte":"La résine est saturée et ne retient plus rien"},{"id":"c","texte":"Le mélange ne contenait aucune molécule au départ"},{"id":"d","texte":"Le lavage est terminé : il ne sort plus rien de non fixé"}],"multiple":false}]}$ex$::jsonb,
