   $ex${"titre":"La vitamine C d’un jus d’orange","competence":"calculer","situation":"Au laboratoire d’une coopérative de fruits, Théo dose la vitamine C d’un jus d’orange en versant du DCPIP, un oxydant bleu qui devient incolore quand la vitamine C le réduit. La réaction est mole à mole. Il titre 10,0 mL de jus, d’abord à la volée, puis avec soin.","documents":[{"id":"reactifs","type":"fiche","modele":"etiquette","entete":"Fiche des réactifs","sousTitre":"Dosage de la vitamine C","emoji":"🍊","lignes":[{"texte":"DCPIP (dans la burette)","valeur":"2,0 × 10⁻³ mol·L⁻¹"},{"texte":"Prise d’essai de jus","valeur":"10,0 mL"},{"texte":"Masse molaire de la vitamine C","valeur":"176 g·mol⁻¹"}],"pied":"Fiche écrite pour l’exercice"},{"id":"titrages","type":"tableau","titre":"Les volumes de DCPIP versés","colonnes":["Titrage","Volume de DCPIP versé (mL)"],"lignes":[["Titrage rapide","12"],["Essai 1","11,1"],["Essai 2","10,9"],["Essai 3","11,0"]],"enteteLignes":true,"source":"Mesures inventées pour l’exercice"}],"questions":[{"enonce":"Touche le volume qui sert seulement à encadrer le volume équivalent.","aide":"Un premier titrage rapide donne une idée du volume avant les essais précis.","type":"zone","document":"titrages","multiple":false},{"enonce":"Comment Théo repère-t-il l’équivalence ?","aide":"Tant qu’il reste de la vitamine C, chaque goutte de DCPIP perd sa coloration.","type":"choix","options":[{"id":"a","texte":"Le DCPIP en excès garde sa coloration bleue"},{"id":"b","texte":"Le jus devient incolore dès la première goutte"},{"id":"c","texte":"Un précipité rouge brique apparaît dans le bécher"},{"id":"d","texte":"Le jus devient rose comme avec la phénolphtaléine"}],"multiple":false},{"enonce":"Calcule le volume équivalent moyen des trois essais précis.","aide":"Additionne les trois essais puis divise par 3.","type":"nombre","unite":"mL"},{"enonce":"Quelle est la concentration en vitamine C du jus, en mmol·L⁻¹ ?","aide":"La réaction est mole à mole : n(DCPIP versé) = n(vitamine C).","type":"nombre","unite":"mmol·L⁻¹"},{"enonce":"Quelle masse de vitamine C le jus contient-il par litre, arrondie au centième ?","aide":"Multiplie la concentration en mol·L⁻¹ par la masse molaire.","type":"nombre","unite":"g·L⁻¹"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Le **titrage rapide** (12 mL) ne sert qu’à encadrer VE : on ralentit ensuite près de ce volume."},{"cle":{"type":"choix","ids":["a"]},"explication":"À l’équivalence, la première goutte de DCPIP en excès **reste bleue** : le titrant sert lui-même d’indicateur."},{"cle":{"type":"nombre","valeur":11,"tolerance":0.05},"affichage":"11 mL","explication":"(11,1 + 10,9 + 11,0) / 3 = 33,0 / 3 = **11,0 mL**."},{"cle":{"type":"nombre","valeur":2.2,"tolerance":0.02},"affichage":"2,2 mmol·L⁻¹","explication":"C1 = C2 × VE / V1 = 2,0 × 10⁻³ × 11,0 / 10,0 = 2,2 × 10⁻³ mol·L⁻¹ = **2,2 mmol·L⁻¹**."},{"cle":{"type":"nombre","valeur":0.39,"tolerance":0.005},"affichage":"0,39 g·L⁻¹","explication":"ρ = 2,2 × 10⁻³ × 176 = 0,387 ≈ **0,39 g·L⁻¹**."}]$ex$::jsonb),
  ('3da787b0-ae06-5dd3-af66-024457285de8'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le vinaigre de la cantine est-il fidèle à son étiquette ?","competence":"resoudre","situation":"Nina contrôle le vinaigre de la cantine. Elle en dilue 10,0 mL dans une fiole jaugée de 100,0 mL, puis titre 10,0 mL de ce vinaigre dilué par de la soude à 0,100 mol·L⁻¹, avec de la phénolphtaléine. L’équation est CH₃COOH + HO⁻ → CH₃COO⁻ + H₂O.","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","entete":"Vinaigre de table","sousTitre":"Étiquette de la bouteille","emoji":"🍶","lignes":[{"texte":"Acidité","valeur":"7 g d’acide éthanoïque pour 100 mL"},{"texte":"Masse molaire de l’acide éthanoïque","valeur":"60 g·mol⁻¹"}],"pied":"Étiquette inventée pour l’exercice"},{"id":"essais","type":"tableau","titre":"Les quatre titrages de Nina","colonnes":["Essai","Volume de soude versé (mL)","Observation"],"lignes":[["1","11,6","rose pâle persistant"],["2","11,8","rose pâle persistant"],["3","11,7","rose pâle persistant"],["4","13,4","rose foncé : équivalence dépassée"]],"enteteLignes":true,"source":"Mesures inventées pour l’exercice"}],"questions":[{"enonce":"Touche le volume que Nina doit écarter du calcul.","aide":"Regarde la colonne « Observation » : un essai a dépassé l’équivalence.","type":"zone","document":"essais","multiple":false},{"enonce":"Calcule le volume équivalent moyen avec les essais retenus.","aide":"Moyenne des trois essais restants.","type":"nombre","unite":"mL"},{"enonce":"Quelle est la concentration de l’acide dans le vinaigre dilué ?","aide":"C1 × V1 = C2 × VE, avec V1 = 10,0 mL.","type":"nombre","unite":"mol·L⁻¹"},{"enonce":"Remets dans l’ordre les bonnes pratiques du titrage.","aide":"On prépare la burette avant de verser, et on contrôle à la fin.","type":"ordre","items":[{"id":"a","texte":"Répéter pour vérifier la répétabilité"},{"id":"b","texte":"Titrer avec précision, goutte à goutte près de l’équivalence"},{"id":"c","texte":"Chasser la bulle d’air et ajuster le zéro"},{"id":"d","texte":"Rincer la burette avec la solution titrante"},{"id":"e","texte":"Faire un titrage rapide pour encadrer VE"}]},{"enonce":"Quelle est la concentration du vinaigre pur, en mol·L⁻¹ ?","aide":"Le vinaigre a été dilué de 10,0 mL à 100,0 mL : quel est le facteur de dilution ?","type":"nombre","unite":"mol·L⁻¹"},{"enonce":"Le vinaigre est-il conforme à son étiquette ?","aide":"Multiplie la concentration molaire par la masse molaire, puis exprime-la pour 100 mL.","type":"choix","options":[{"id":"a","texte":"Oui : 70 g·L⁻¹ soit 7 g pour 100 mL"},{"id":"b","texte":"Non : 117 g·L⁻¹, trop concentré"},{"id":"c","texte":"Non : 7 g·L⁻¹, trop dilué"},{"id":"d","texte":"Oui : 1,17 g·L⁻¹ soit 7 g pour 100 mL"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c1"]},"explication":"L’essai 4 a dépassé l’équivalence (rose foncé) : son volume de **13,4 mL** n’est pas le volume équivalent."},{"cle":{"type":"nombre","valeur":11.7,"tolerance":0.05},"affichage":"11,7 mL","explication":"(11,6 + 11,8 + 11,7) / 3 = 35,1 / 3 = **11,7 mL**."},{"cle":{"type":"nombre","valeur":0.117,"tolerance":0.001},"affichage":"0,117 mol·L⁻¹","explication":"C1 = 0,100 × 11,7 / 10,0 = **0,117 mol·L⁻¹**."},{"cle":{"type":"ordre","ids":["d","c","e","b","a"]},"explication":"On **prépare la burette**, on encadre VE par un titrage rapide, on titre avec précision, puis on répète pour vérifier la **répétabilité**."},{"cle":{"type":"nombre","valeur":1.17,"tolerance":0.01},"affichage":"1,17 mol·L⁻¹","explication":"F = 100,0 / 10,0 = 10 ; C = 0,117 × 10 = **1,17 mol·L⁻¹**."},{"cle":{"type":"choix","ids":["a"]},"explication":"ρ = 1,17 × 60 = 70,2 g·L⁻¹ ≈ 70 g·L⁻¹, soit environ **7 g pour 100 mL** : l’étiquette est respectée."}]$ex$::jsonb),
  ('32c42eb9-92a3-5667-b808-7103fc2e356d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Droit, morale ou les deux ?","competence":"analyser-document","situation":"Samir, délégué de classe, note cinq situations croisées dans la semaine. Il se demande lesquelles relèvent du droit, de la morale, ou des deux.","documents":[{"id":"sit","type":"tableau","titre":"Les situations de la semaine","source":"Situation imaginée pour l’exercice.","colonnes":["n°","Situation"],"enteteLignes":true,"lignes":[["1","Un automobiliste roule à 55 km/h dans une rue limitée à 50 km/h."],["2","Une élève ment à son amie sur sa note de maths."],["3","Un patron refuse d’embaucher un candidat à cause de son origine."],["4","Un voisin frappe un autre voisin pendant une dispute."],["5","Un passant ne dit pas merci à celui qui lui tient la porte."]]}],"questions":[{"enonce":"Touche la situation qui n’a rien d’immoral mais que l’autorité publique sanctionne d’une amende.","aide":"Cherche une règle qui sert l’ordre social sans toucher à la conscience de chacun.","type":"zone","document":"sit","multiple":false},{"enonce":"Range chaque situation : règle de droit seulement, règle morale seulement, ou les deux ?","aide":"Pour le droit, demande-toi s’il existe une sanction prononcée par l’État.","type":"categories","categories":[{"id":"c0","texte":"Droit seulement"},{"id":"c1","texte":"Morale ou politesse seulement"},{"id":"c2","texte":"Droit et morale à la fois"}],"items":[{"id":"i0","texte":"Situation 5 : ne pas dire merci"},{"id":"i1","texte":"Situation 4 : coups entre voisins"},{"id":"i2","texte":"Situation 2 : mentir à son amie"},{"id":"i3","texte":"Situation 3 : refus d’embauche discriminatoire"},{"id":"i4","texte":"Situation 1 : 55 km/h en zone 50"}]},{"enonce":"Quel principe du droit français la situation 3, le refus d’embauche à cause de l’origine, viole-t-elle ?","aide":"Même règle pour tous ceux qui sont dans la même situation.","type":"choix","options":[{"id":"a","texte":"Le principe d’égalité"},{"id":"b","texte":"Le principe de laïcité"},{"id":"c","texte":"La liberté d’expression"},{"id":"d","texte":"Le principe de solidarité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Rouler à 55 km/h en ville n’a rien d’immoral, mais la règle de droit est **sanctionnée par l’État** (amende) : **situation 1**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c2","i4":"c0"}},"explication":"Mentir à un ami ou oublier de dire merci n’est pas sanctionné par le droit. Discriminer et frapper sont **à la fois immoraux et punis par la loi**. L’excès de vitesse est puni sans être immoral."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les discriminations à l’embauche sont interdites par le principe d’**égalité**."}]$ex$::jsonb),
  ('32c42eb9-92a3-5667-b808-7103fc2e356d'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un salaire sous le SMIC","competence":"analyser-document","situation":"Léa, 18 ans, vient de signer son premier contrat de travail dans une boutique de Rouen. Sa grande sœur relit le document et fronce les sourcils.","documents":[{"id":"contrat","type":"fiche","modele":"affiche","entete":"Contrat de travail","sousTitre":"Boutique Mode & Co — Rouen","emoji":"📄","source":"Extrait imaginé pour l’exercice.","lignes":[{"texte":"Lieu de travail : boutique de Rouen","id":"z1"},{"texte":"Début du contrat : 1er septembre","id":"z2"},{"texte":"Salaire : inférieur au SMIC, accepté par la salariée","id":"z3"},{"texte":"Tenue de travail fournie par la boutique","id":"z4"}],"pied":"Lu et approuvé : Léa et la gérante","teinte":"violet"}],"questions":[{"enonce":"Touche la clause que le droit refuse, même si les deux parties l’ont acceptée.","aide":"Une règle d’ordre public protège le salarié, quoi qu’il signe.","type":"zone","document":"contrat","multiple":false},{"enonce":"Léa est d’accord avec cette clause. Que change son accord ?","aide":"Pense à l’exemple des voisins qui « achètent » l’impunité.","type":"choix","options":[{"id":"a","texte":"La clause est valable si un seul des deux est d’accord"},{"id":"b","texte":"Tout : la clause devient valable puisque Léa a signé"},{"id":"c","texte":"La clause devient valable si la gérante la relit en public"},{"id":"d","texte":"Rien : la règle d’ordre public s’impose malgré l’accord"}],"multiple":false},{"enonce":"Associe chaque règle à la fonction du droit qu’elle illustre.","aide":"Le salarié est la partie la plus faible dans un contrat de travail.","type":"association","gauche":[{"id":"g0","texte":"Interdire de payer sous le SMIC"},{"id":"g1","texte":"Fixer le fonctionnement d’une société commerciale"},{"id":"g2","texte":"Offrir un juge pour trancher un conflit entre voisins"},{"id":"g3","texte":"Encadrer les données personnelles avec le RGPD"}],"droite":[{"id":"d0","texte":"Faire évoluer la société"},{"id":"d1","texte":"Organiser la société"},{"id":"d2","texte":"Protéger les personnes"},{"id":"d3","texte":"Pacifier les relations"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **SMIC** relève de l’**ordre public** : on ne peut pas y déroger par contrat. La clause de salaire est nulle."},{"cle":{"type":"choix","ids":["d"]},"explication":"On ne peut pas écarter une règle d’**ordre public** par un accord : la clause est **nulle**, même signée par Léa."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Le SMIC **protège** le salarié ; le droit des sociétés **organise** ; le juge **pacifie** ; le RGPD **fait évoluer** le droit avec la technique."}]$ex$::jsonb),
  ('32c42eb9-92a3-5667-b808-7103fc2e356d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le maire qui défie le juge","competence":"argumenter","situation":"Dans la ville imaginaire de Valmont, un arrêté du maire est annulé par un juge, mais le maire refuse d’obéir. Un lycéen en cours de droit doit dire en quoi cela menace l’État de droit.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"L’affaire de la piscine de Valmont","source":"Texte écrit pour l’exercice.","blocs":["Le 3 mars, le maire de Valmont interdit par arrêté l’entrée de la piscine municipale aux habitants d’une certaine origine.","Une association saisit le tribunal administratif.","Le 20 avril, le juge, indépendant du maire, annule l’arrêté.","Le maire déclare alors qu’il n’appliquera pas la décision : « Ici, c’est moi qui commande. »"]},{"id":"principes","type":"tableau","titre":"Les grands principes","source":"D’après le cours.","colonnes":["Principe","Ce qu’il signifie"],"enteteLignes":true,"lignes":[["Liberté","Chacun agit tant qu’il ne nuit pas à autrui"],["Égalité","Même règle pour tous ceux dans la même situation"],["Solidarité","La collectivité protège les plus fragiles"],["Laïcité","L’État est neutre et garantit la liberté de conscience"]]}],"questions":[{"enonce":"Touche le principe que l’arrêté du 3 mars méconnaît.","aide":"L’arrêté traite des habitants différemment selon leur origine.","type":"zone","document":"principes","multiple":false},{"enonce":"Range ces faits : illustrent-ils l’État de droit ou l’arbitraire ?","aide":"Dans un État de droit, même celui qui écrit la règle y est soumis.","type":"categories","categories":[{"id":"c0","texte":"État de droit"},{"id":"c1","texte":"Arbitraire"}],"items":[{"id":"i0","texte":"Une association peut contester l’arrêté devant un juge"},{"id":"i1","texte":"L’arrêté vise des habitants à cause de leur origine"},{"id":"i2","texte":"Le maire refuse d’appliquer la décision du juge"},{"id":"i3","texte":"Un juge indépendant annule l’arrêté"}]},{"enonce":"Que doit faire le maire après la décision du 20 avril ?","aide":"Personne n’est au-dessus des règles, pas même celui qui les écrit.","type":"choix","options":[{"id":"a","texte":"Choisir librement s’il obéit ou non au jugement"},{"id":"b","texte":"Se conformer à la décision du juge, comme tout citoyen"},{"id":"c","texte":"Appliquer l’arrêté tant qu’une loi ne l’interdit pas"},{"id":"d","texte":"Attendre que le préfet l’autorise à lui obéir"}],"multiple":false},{"enonce":"Complète la conclusion.","aide":"Relis la citation du cours sur l’État de droit.","type":"trous","segments":["L’État de droit est l’inverse de l’",0," : le maire est soumis au ",1," comme n’importe quel citoyen."],"banque":["droit","pouvoir","arbitraire","hasard"]}]}$ex$::jsonb,
