  ('0b3ea662-ccfd-5020-8692-9f35bfb8506b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre règles, une seule règle de droit","competence":"analyser-document","situation":"Dans une petite ville, Yanis voit quatre règles affichées ou annoncées autour de lui. Une seule est une vraie règle de droit.","documents":[{"id":"regles","type":"tableau","titre":"Quatre règles","source":"Situation imaginée pour l’exercice.","colonnes":["n°","Règle"],"enteteLignes":true,"lignes":[["1","Un texte de loi : « Les salariés ont droit à des congés payés. »"],["2","Le règlement du club de football : « Les crampons moulés sont obligatoires. »"],["3","Une décision visant une seule personne : « Monsieur Durand paiera 300 € à Mme Petit. »"],["4","Une affiche sans auteur connu : « Interdit de garer sa voiture ici. »"]]}],"questions":[{"enonce":"Touche la règle qui réunit les trois caractères de la règle de droit.","aide":"Il faut une règle générale, obligatoire et légitime.","type":"zone","document":"regles","multiple":false},{"enonce":"Associe chaque règle au caractère qui lui manque, ou à sa conclusion.","aide":"Pour chaque règle, demande-toi : à qui s’applique-t-elle ? Qui peut la sanctionner ? Qui l’a écrite ?","type":"association","gauche":[{"id":"g0","texte":"La règle n° 1"},{"id":"g1","texte":"La règle n° 2"},{"id":"g2","texte":"La règle n° 3"},{"id":"g3","texte":"La règle n° 4"}],"droite":[{"id":"d0","texte":"Non générale : elle vise une personne"},{"id":"d1","texte":"Non sanctionnée par l’État"},{"id":"d2","texte":"Non légitime : auteur inconnu"},{"id":"d3","texte":"Générale, obligatoire et légitime"}]},{"enonce":"Quel caractère de la règle garantit l’égalité devant la loi ?","aide":"Une règle qui vise une catégorie de personnes traite chacun de la même façon.","type":"choix","options":[{"id":"a","texte":"Le caractère général"},{"id":"b","texte":"Le caractère légitime"},{"id":"c","texte":"Le caractère obligatoire"},{"id":"d","texte":"Le caractère exécutoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La loi sur les congés payés est **générale** (tous les salariés), **obligatoire** (sanctionnée par l’État) et **légitime** (le Parlement est compétent)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Le règlement d’un club n’est pas sanctionné par l’État ; la décision sur M. Durand est **individuelle** ; l’affiche n’émane d’**aucune autorité compétente**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une règle **générale** vise une catégorie de personnes, pas un individu nommé : elle garantit l’**égalité**."}]$ex$::jsonb),
