   $ex${"titre":"Deux acheteurs, un même ordinateur","competence":"raisonner","situation":"Hugo, étudiant, et Mme Faure, gérante d’une boulangerie, commandent le même ordinateur portable sur un site de vente. Tous deux veulent le renvoyer. A-t-on le droit de se rétracter ?","documents":[{"id":"cas","type":"tableau","titre":"Les deux commandes","source":"Situation imaginée pour l’exercice.","colonnes":["Acheteur","Usage prévu","Réception"],"enteteLignes":true,"lignes":[["Hugo, étudiant","Ses cours et ses loisirs","12 juin"],["Mme Faure, gérante","La caisse de sa boulangerie","12 juin"]]},{"id":"methode","type":"chaine","titre":"La méthode du cas pratique","disposition":"ligne","noeuds":[{"id":"z1","texte":"Faits"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Problème de droit"},{"id":"z4","texte":"Règle"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"On écrit : « Hugo est un consommateur, le site est un professionnel ». Touche l’étape de la méthode correspondante.","aide":"Cette étape nomme juridiquement les personnes et les faits.","type":"zone","document":"methode","multiple":false},{"enonce":"Quel énoncé formule correctement le problème de droit, qui se pose en termes généraux ?","aide":"Pas de prénom ni de montant : on pose la question pour toute une catégorie de personnes.","type":"choix","options":[{"id":"a","texte":"Hugo est-il plus protégé que la gérante d’une boulangerie ?"},{"id":"b","texte":"Le site doit-il rembourser 640 euros à cet étudiant ?"},{"id":"c","texte":"Hugo a-t-il le droit de renvoyer son ordinateur le 20 juin ?"},{"id":"d","texte":"Un consommateur peut-il revenir sur un achat conclu à distance ?"}],"multiple":false},{"enonce":"Hugo a reçu l’ordinateur le 12 juin et dispose de 14 jours. Quel jour de juin se termine son délai ?","aide":"Ajoute 14 au 12.","type":"nombre","unite":"juin"},{"enonce":"Pourquoi Mme Faure ne peut-elle pas, en principe, invoquer ce délai de rétractation ?","aide":"Relis la définition du consommateur dans le cours.","type":"choix","options":[{"id":"a","texte":"Elle agit pour son activité : ce n’est pas une consommatrice"},{"id":"b","texte":"Elle a reçu son colis après le 12 juin, donc trop tard"},{"id":"c","texte":"Elle est majeure alors qu’un étudiant est protégé"},{"id":"d","texte":"Elle est une personne physique, donc non protégée"}],"multiple":false}]}$ex$::jsonb,
