   $ex${"titre":"Trois adultes, trois protections","competence":"analyser-document","situation":"Le juge des tutelles examine trois dossiers de majeurs dont les facultés sont altérées. Il doit choisir la mesure la mieux adaptée à chacun.","documents":[{"id":"mesures","type":"tableau","titre":"Les trois mesures","source":"D’après le cours.","colonnes":["Mesure","Protection","Qui agit ?"],"enteteLignes":true,"lignes":[["Sauvegarde de justice","Légère, temporaire","La personne ; actes annulables s’ils lui nuisent"],["Curatelle","Moyenne","La personne, assistée d’un curateur"],["Tutelle","Forte","Le tuteur la représente"]]},{"id":"dossiers","type":"tableau","titre":"Les trois dossiers","source":"Situation imaginée pour l’exercice.","colonnes":["Personne","Situation"],"enteteLignes":true,"lignes":[["Mme Lemoine","Ses facultés sont gravement altérées : elle ne peut plus gérer seule ses affaires."],["M. Petit","Il gère seul sa vie courante mais doit être conseillé pour les actes importants."],["Mlle Colin","Trouble passager pendant une hospitalisation."]]}],"questions":[{"enonce":"Associe chaque personne à la mesure adaptée.","aide":"Plus l’altération est grave, plus la protection est forte.","type":"association","gauche":[{"id":"g0","texte":"Mme Lemoine"},{"id":"g1","texte":"M. Petit"},{"id":"g2","texte":"Mlle Colin"}],"droite":[{"id":"d0","texte":"La tutelle"},{"id":"d1","texte":"La sauvegarde de justice"},{"id":"d2","texte":"La curatelle"}]},{"enonce":"Touche la mesure où la personne n’agit pas elle-même mais est représentée.","aide":"Représenter, c’est agir au nom et pour le compte d’autrui.","type":"zone","document":"mesures","multiple":false},{"enonce":"M. Petit veut vendre son appartement. Comment doit-il procéder, sous curatelle ?","aide":"Sous curatelle, la personne agit, mais pas seule pour les actes importants.","type":"choix","options":[{"id":"a","texte":"Il agit seul sans aucune assistance"},{"id":"b","texte":"Il demande à son voisin de signer"},{"id":"c","texte":"Son curateur agit seul à sa place"},{"id":"d","texte":"Il agit lui-même, assisté de son curateur"}],"multiple":false},{"enonce":"Range ces actes : administration ou disposition ?","aide":"Un acte de disposition engage durablement le patrimoine.","type":"categories","categories":[{"id":"c0","texte":"Acte d’administration"},{"id":"c1","texte":"Acte de disposition"}],"items":[{"id":"i0","texte":"Faire une donation"},{"id":"i1","texte":"Vendre une maison"},{"id":"i2","texte":"Emprunter une grosse somme"},{"id":"i3","texte":"Faire des réparations"},{"id":"i4","texte":"Encaisser des loyers"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Altération grave : **tutelle**. Besoin d’assistance pour les actes importants : **curatelle**. Trouble passager : **sauvegarde de justice**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Dans la **tutelle**, le tuteur **représente** la personne protégée."},{"cle":{"type":"choix","ids":["d"]},"explication":"En **curatelle**, la personne agit elle-même, **assistée** de son curateur pour les actes importants."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"La **gestion courante** est un acte d’administration ; **vendre, donner, emprunter beaucoup** engagent durablement le patrimoine : actes de disposition."}]$ex$::jsonb),
  ('b90b4995-a79d-50f5-af64-5ebc98df0f23'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le patrimoine de Mme Benoit","competence":"raisonner","situation":"Mme Benoit, 79 ans, est placée sous tutelle. Sa tutrice dresse l’inventaire de son patrimoine avant de décider s’il faut vendre la maison.","documents":[{"id":"inventaire","type":"tableau","titre":"L’inventaire de Mme Benoit","source":"Chiffres imaginés pour l’exercice.","colonnes":["Élément","Nature","Valeur"],"enteteLignes":true,"lignes":[["Maison","Bien","180 000 €"],["Voiture","Bien","7 500 €"],["Épargne","Créance sur la banque","12 500 €"],["Prêt immobilier restant","Dette","74 000 €"],["Facture de garage à payer","Dette","1 200 €"],["Droit à l’image","Droit de la personnalité","non évaluable"]]},{"id":"decision","type":"texte","genre":"source","titre":"Extrait de la décision","source":"Texte écrit pour l’exercice.","blocs":["Mme Benoit est placée sous tutelle. Sa tutrice la représente dans les actes de la vie civile ; elle ne peut pas vendre le logement sans l’autorisation du juge."]}],"questions":[{"enonce":"Touche la ligne qui n’entre pas dans le patrimoine de Mme Benoit.","aide":"Le patrimoine ne comprend que ce qui s’évalue en argent.","type":"zone","document":"inventaire","multiple":false},{"enonce":"Quel est le montant de l’actif, c’est-à-dire des biens et créances, en euros ?","aide":"Additionne la maison, la voiture et l’épargne.","type":"nombre","unite":"€"},{"enonce":"Le passif correspond aux dettes (prêt et facture de garage). Quelle est la valeur nette du patrimoine, actif moins passif, en euros ?","aide":"Passif = 74 000 + 1 200 = 75 200 €. Soustrais-le de l’actif de 200 000 €.","type":"nombre","unite":"€"},{"enonce":"Touche le mot qui désigne la mesure de protection de Mme Benoit.","aide":"C’est la mesure la plus protectrice : la personne est représentée.","type":"zone","document":"decision","multiple":false},{"enonce":"Pourquoi la tutrice doit-elle demander l’autorisation du juge pour vendre la maison ?","aide":"Plus l’acte est grave, plus la protection est forte.","type":"choix","options":[{"id":"a","texte":"C’est un acte de la vie courante pour une majeure"},{"id":"b","texte":"C’est un droit de la personnalité qu’on ne peut céder"},{"id":"c","texte":"C’est un acte d’administration de gestion courante"},{"id":"d","texte":"C’est un acte de disposition qui engage durablement le patrimoine"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r5c0"]},"explication":"Le **droit à l’image** est extrapatrimonial : il n’est pas évaluable en argent, donc hors du patrimoine."},{"cle":{"type":"nombre","valeur":200000,"tolerance":0},"affichage":"200 000 €","explication":"180 000 + 7 500 + 12 500 = **200 000 €**."},{"cle":{"type":"nombre","valeur":124800,"tolerance":0},"affichage":"124 800 €","explication":"Passif : 74 000 + 1 200 = 75 200 €. Valeur nette : 200 000 − 75 200 = **124 800 €**."},{"cle":{"type":"zone","ids":["m5"]},"explication":"Mme Benoit est sous **tutelle** : sa tutrice la représente."},{"cle":{"type":"choix","ids":["d"]},"explication":"Vendre la maison est un **acte de disposition** : il engage durablement le patrimoine, donc le juge doit l’autoriser."}]$ex$::jsonb),
