   $ex${"titre":"La photo de la soirée","competence":"analyser-document","situation":"Maëlys, 16 ans, découvre sur un réseau social une photo d’elle prise à une soirée privée, publiée par un camarade avec un commentaire moqueur.","documents":[{"id":"post","type":"fiche","modele":"affiche","entete":"Publication","sousTitre":"Réseau social — texte imaginé","emoji":"📱","lignes":[{"texte":"Auteur : Dylan, camarade de classe","id":"z1"},{"texte":"Photo : Maëlys à la soirée de Léa, sans son accord","id":"z2"},{"texte":"Commentaire : une moquerie sur son apparence","id":"z3"},{"texte":"Visible par tous les abonnés de Dylan","id":"z4"}],"teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui porte atteinte au droit à l’image de Maëlys.","aide":"Le droit à l’image protège contre la diffusion sans consentement.","type":"zone","document":"post","multiple":false},{"enonce":"Maëlys est mineure. Quel consentement faut-il pour diffuser son image ?","aide":"Pour un mineur, l’autorisation des parents est nécessaire.","type":"choix","options":[{"id":"a","texte":"Celui du directeur du lycée"},{"id":"b","texte":"Celui de Dylan seul"},{"id":"c","texte":"Celui de ses parents"},{"id":"d","texte":"Aucun, une photo se diffuse librement"}],"multiple":false},{"enonce":"Associe chaque caractère des droits de la personnalité à sa signification.","aide":"Le préfixe « in- » exprime ce qui est impossible.","type":"association","gauche":[{"id":"g0","texte":"Inaliénables"},{"id":"g1","texte":"Insaisissables"},{"id":"g2","texte":"Imprescriptibles"},{"id":"g3","texte":"Intransmissibles"}],"droite":[{"id":"d0","texte":"Ils s’éteignent en principe au décès"},{"id":"d1","texte":"On ne peut ni les vendre ni y renoncer définitivement"},{"id":"d2","texte":"On ne les perd pas en ne les utilisant pas"},{"id":"d3","texte":"Aucun créancier ne peut les saisir"}]}]}$ex$::jsonb,
