   $ex${"titre":"Quelles données sont personnelles ?","competence":"analyser-document","situation":"Un site de jeux demande aux nouveaux joueurs une série d’informations. Un lycéen doit repérer celles qui relèvent du RGPD et celles qui n’en relèvent pas.","documents":[{"id":"donnees","type":"tableau","titre":"Les informations demandées","source":"Situation imaginée pour l’exercice.","colonnes":["Information","Exemple"],"enteteLignes":true,"lignes":[["Nom et prénom","Lina Moreau"],["Adresse IP de l’ordinateur","192.168.4.12"],["Nombre de joueurs inscrits dans le monde","1 200 000"],["Numéro de téléphone","06 00 00 00 00"],["Moyenne anonyme du temps de jeu de tous les joueurs","42 minutes par jour"]]}],"questions":[{"enonce":"Touche les trois informations qui sont des données à caractère personnel.","aide":"Une donnée personnelle permet d’identifier une personne, directement ou non.","type":"zone","document":"donnees","multiple":true},{"enonce":"Range ces traces numériques : formelles ou informelles ?","aide":"Une trace formelle est volontairement publiée ; une trace informelle se crée sans qu’on y pense.","type":"categories","categories":[{"id":"c0","texte":"Traces formelles"},{"id":"c1","texte":"Traces informelles"}],"items":[{"id":"i0","texte":"Mes publications"},{"id":"i1","texte":"Ma géolocalisation"},{"id":"i2","texte":"Le profil que je remplis"},{"id":"i3","texte":"Mon historique de navigation"}]},{"enonce":"Associe chaque droit RGPD à ce qu’il permet.","aide":"Le droit à l’effacement est aussi appelé droit à l’oubli.","type":"association","gauche":[{"id":"g0","texte":"Le droit d’accès"},{"id":"g1","texte":"Le droit de rectification"},{"id":"g2","texte":"Le droit à l’effacement"},{"id":"g3","texte":"Le droit à la portabilité"}],"droite":[{"id":"d0","texte":"Récupérer ses données pour les emporter ailleurs"},{"id":"d1","texte":"Corriger une donnée inexacte"},{"id":"d2","texte":"Savoir quelles données sont détenues"},{"id":"d3","texte":"Faire supprimer ses données"}]},{"enonce":"Le site Jeuzone a un chiffre d’affaires mondial de 500 millions d’euros. La CNIL peut sanctionner jusqu’à 4 % du chiffre d’affaires mondial. Quel est le maximum, en millions d’euros ?","aide":"4 % de 500 = 0,04 × 500.","type":"nombre","unite":"M€"}]}$ex$::jsonb,
