   $ex${"titre":"Le réseau social et Noé, 14 ans","competence":"argumenter","situation":"Noé, 14 ans, s’inscrit sur Chatzone, un réseau social imaginaire. Il n’a pas lu la politique de confidentialité, que sa grande sœur trouve très gourmande en données.","documents":[{"id":"politique","type":"fiche","modele":"affiche","entete":"Chatzone — politique de confidentialité","sousTitre":"Résumé imaginé pour l’exercice","emoji":"🔒","lignes":[{"texte":"Finalité : proposer un fil d’actualité des amis","id":"z1"},{"texte":"Données collectées : nom, e-mail, date de naissance","id":"z2"},{"texte":"Collecte aussi : géolocalisation en continu et liste de contacts","id":"z3"},{"texte":"Consentement : case déjà cochée à l’inscription","id":"z4"},{"texte":"Durée de conservation : illimitée","id":"z5"}],"teinte":"bleu"},{"id":"droits","type":"tableau","titre":"Ce que Noé voudrait faire","source":"Situation imaginée pour l’exercice.","colonnes":["Souhait","Droit RGPD"],"enteteLignes":true,"lignes":[["Voir tout ce que Chatzone détient sur lui","?"],["Faire supprimer ses publications","?"],["Faire corriger sa date de naissance","?"]]}],"questions":[{"enonce":"Touche la ligne qui contredit le principe de minimisation, vu la finalité annoncée.","aide":"Pour un fil d’actualité, a-t-on besoin de suivre la position de l’utilisateur en continu ?","type":"zone","document":"politique","multiple":false},{"enonce":"Touche la ligne qui ne respecte pas l’exigence d’un consentement libre, éclairé et explicite.","aide":"Une case déjà cochée demande-t-elle un geste volontaire ?","type":"zone","document":"politique","multiple":false},{"enonce":"Noé a 14 ans. Peut-il consentir seul au traitement de ses données par ce réseau social en France ?","aide":"Le seuil en France est de 15 ans.","type":"choix","options":[{"id":"a","texte":"Oui, si la case est déjà cochée par le site"},{"id":"b","texte":"Oui : à partir de 13 ans, sans rien demander"},{"id":"c","texte":"Non : seul le site peut décider pour lui"},{"id":"d","texte":"Non : il faut l’accord de ses parents avant 15 ans"}],"multiple":false},{"enonce":"Chatzone a un chiffre d’affaires mondial de 1 800 millions d’euros. Quelle est la sanction maximale de la CNIL, à 4 % de ce chiffre, en millions d’euros ?","aide":"4 % de 1 800 = 0,04 × 1 800.","type":"nombre","unite":"M€"},{"enonce":"Associe chaque souhait de Noé au droit RGPD correspondant.","aide":"Accès, rectification, effacement : un nom pour chaque geste.","type":"association","gauche":[{"id":"g0","texte":"Voir tout ce que Chatzone détient sur lui"},{"id":"g1","texte":"Faire supprimer ses publications"},{"id":"g2","texte":"Faire corriger sa date de naissance"}],"droite":[{"id":"d0","texte":"Le droit de rectification"},{"id":"d1","texte":"Le droit à l’effacement"},{"id":"d2","texte":"Le droit d’accès"}]}]}$ex$::jsonb,
