  ('00d72e69-5f60-5886-bf83-64cd973be88b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les biens de Salomé, étudiante et commerçante","competence":"lire-tableau","situation":"Salomé, étudiante à Nantes, vend des bougies sur Internet. Elle possède plusieurs biens, matériels ou non : le tableau dit ce qu’elle en fait.","documents":[{"id":"biens","type":"tableau","titre":"Les biens de Salomé","source":"Situation imaginée pour l’exercice.","colonnes":["Bien de Salomé","Ce qu’elle en fait"],"lignes":[["Un appartement à Nantes","Elle loue une chambre à un étudiant, 640 € par mois pendant 9 mois"],["Un scooter","Elle s’en sert pour aller en cours"],["Le nom « Bulle de Lune »","Elle l’a fait déposer à l’INPI pour sa boutique en ligne"],["Ses droits d’auteur sur les photos du site","Elle a pris elle-même toutes les photos"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux biens qui n’ont pas d’existence matérielle.","aide":"Un bien incorporel ne se touche pas : c’est un droit, un signe, une création.","type":"zone","document":"biens","multiple":true},{"enonce":"Quel total de loyers Salomé encaisse-t-elle sur les 9 mois de location de la chambre ?","aide":"Multiplie le loyer mensuel par le nombre de mois.","type":"nombre","unite":"€"},{"enonce":"Relie chaque geste de Salomé à l’attribut du droit de propriété qu’il exerce.","aide":"Utiliser, percevoir les fruits, disposer : trouve le verbe de chaque geste.","type":"association","gauche":[{"id":"g0","texte":"Rouler en scooter pour aller en cours"},{"id":"g1","texte":"Encaisser les loyers de la chambre"},{"id":"g2","texte":"Vendre son scooter à la fin de l’année"}],"droite":[{"id":"d0","texte":"Fructus : percevoir les fruits"},{"id":"d1","texte":"Usus : utiliser la chose"},{"id":"d2","texte":"Abusus : disposer de la chose"}]}]}$ex$::jsonb,
