  ('00d72e69-5f60-5886-bf83-64cd973be88b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fumée de la pizzeria de Karim","competence":"argumenter","situation":"Lucie vit au-dessus de la pizzeria « Chez Karim », ouverte en mars. Elle a écrit au gérant : le four à bois enfume son salon. Karim, lui, répond qu’il respecte toutes les règles de sécurité.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"La lettre de Lucie Perrin","source":"Texte écrit pour l’exercice.","blocs":["Monsieur, depuis l’ouverture de votre pizzeria, votre four à bois rejette chaque soir, de 18 h à 23 h, une épaisse fumée qui entre dans mon salon.","Mon linge sent la cendre, je ne peux plus ouvrir mes fenêtres, et cela dure depuis des mois. Je vous demande de réparer ce dommage."]},{"id":"frais","type":"tableau","titre":"Les dépenses de Lucie depuis mars","source":"Montants imaginés pour l’exercice.","colonnes":["Dépense","Montant (€)"],"lignes":[["Lavage des rideaux",85],["Linge repris à la teinturerie",120],["Purificateur d’air",195]],"enteteLignes":true}],"questions":[{"enonce":"Touche les mots qui montrent que la gêne se répète régulièrement.","aide":"Cherche l’expression qui donne le rythme de la nuisance.","type":"zone","document":"lettre","multiple":true},{"enonce":"Lucie doit-elle prouver une faute de Karim pour obtenir réparation ?","aide":"Dans le trouble anormal de voisinage, regarde le trouble subi, pas le comportement du voisin.","type":"choix","options":[{"id":"a","texte":"Non : il suffit que le trouble dépasse les inconvénients normaux du voisinage"},{"id":"b","texte":"Oui : sans faute de Karim, aucune réparation n’est jamais possible"},{"id":"c","texte":"Oui : elle doit prouver que Karim veut volontairement lui nuire"},{"id":"d","texte":"Non : mais seulement si Karim a déjà été condamné pour une faute"}],"multiple":false},{"enonce":"Remets dans l’ordre le raisonnement juridique appliqué à cette situation.","aide":"On qualifie les faits, puis on énonce la règle, enfin on conclut.","type":"ordre","items":[{"id":"a","texte":"Règle : nul ne doit causer à autrui un trouble anormal de voisinage"},{"id":"b","texte":"Qualification : Karim exerce son droit de propriété, Lucie subit une fumée répétée"},{"id":"c","texte":"Solution : Lucie peut obtenir réparation et des mesures pour réduire la fumée"}]},{"enonce":"Quelle somme de frais Lucie peut-elle réclamer au total, en euros ?","aide":"Additionne les trois dépenses du tableau.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m13"]},"explication":"**« chaque soir »** : la fumée revient tous les jours. Un trouble répété et durable est plus facilement jugé anormal."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le voisin obtient réparation **sans avoir à prouver une faute** : il suffit que le trouble soit anormal. Que Karim respecte les règles de sécurité ne change rien."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"La méthode est toujours la même : **qualification, règle, solution**."},{"cle":{"type":"nombre","valeur":400,"tolerance":0},"affichage":"400 €","explication":"85 + 120 + 195 = **400 €** de frais à réclamer en réparation du trouble."}]$ex$::jsonb),
