   $ex${"titre":"Le renard de Camille sur 200 T-shirts","competence":"analyser-document","situation":"Camille, illustratrice, découvre que Yanis vend des T-shirts ornés de son dessin de renard. Il lui répond par SMS. Que dit le droit de la propriété intellectuelle ?","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les SMS de Camille et Yanis","source":"Échange imaginé pour l’exercice.","participants":[{"nom":"Camille","emoji":"👩","cote":"gauche"},{"nom":"Yanis","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Yanis","texte":"J’ai imprimé ton renard sur 200 T-shirts, je les vends 25 € pièce."},{"qui":"Camille","texte":"Tu ne m’as rien demandé !"},{"qui":"Yanis","texte":"Tu n’as rien déposé nulle part, donc c’est libre de droits."},{"qui":"Camille","texte":"Je l’ai dessiné en 2024. Il est à moi, et je veux qu’on cite mon nom."}]},{"id":"durees","type":"tableau","titre":"Les durées de protection","source":"Résumé du cours.","colonnes":["Droit","Durée"],"lignes":[["Droit moral de l’auteur","Perpétuel et inaliénable"],["Droits patrimoniaux de l’auteur","Sa vie entière + 70 ans après sa mort"],["Marque déposée","10 ans, renouvelables indéfiniment"],["Brevet","20 ans"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui décrit la reproduction du dessin faite sans autorisation.","aide":"Cherche le verbe de la première réplique de Yanis.","type":"zone","document":"sms","multiple":false},{"enonce":"Comment s’appelle l’atteinte à un droit de propriété intellectuelle ? (un mot)","aide":"Ce mot désigne aussi la fabrication de faux sacs de luxe.","type":"texte","placeholder":"Un mot"},{"enonce":"Que penser de l’argument de Yanis : « Tu n’as rien déposé nulle part, donc c’est libre » ?","aide":"Le dépôt à l’INPI concerne les marques et les brevets, pas le droit d’auteur.","type":"choix","options":[{"id":"a","texte":"Il a tort : mais Camille doit d’abord payer pour obtenir cette protection"},{"id":"b","texte":"Il a tort : une œuvre originale est protégée dès sa création, sans aucune formalité"},{"id":"c","texte":"Il a raison : un dessin n’est protégé qu’après dix ans d’existence"},{"id":"d","texte":"Il a raison : seule une œuvre déposée à l’INPI est protégée par la loi"}],"multiple":false},{"enonce":"Range chaque prérogative de Camille dans la bonne catégorie de droits.","aide":"Le droit moral protège la personne de l’auteur ; les droits patrimoniaux protègent son revenu.","type":"categories","categories":[{"id":"c0","texte":"Droit moral"},{"id":"c1","texte":"Droits patrimoniaux"}],"items":[{"id":"i0","texte":"Toucher une rémunération sur les ventes"},{"id":"i1","texte":"Autoriser ou interdire l’impression sur des T-shirts"},{"id":"i2","texte":"Être citée comme l’auteur du dessin"},{"id":"i3","texte":"S’opposer à une déformation du renard"}]},{"enonce":"Le dessinateur fictif Armand Roche est mort en 1985. En quelle année ses droits patrimoniaux s’éteignent-ils ?","aide":"Reprends la durée des droits patrimoniaux dans le tableau.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"Yanis a **imprimé** le dessin sur des T-shirts : c’est une reproduction, un droit patrimonial réservé à l’auteur."},{"cle":{"type":"texte","acceptes":["contrefacon","la contrefacon"]},"affichage":"contrefaçon","explication":"Reproduire une œuvre sans l’accord de son auteur est une **contrefaçon**, sanctionnée civilement et pénalement."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le droit d’auteur naît **dès la création** de l’œuvre originale, sans dépôt ni formalité. Le dépôt à l’INPI est réservé à la propriété industrielle."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Paternité et respect de l’œuvre relèvent du **droit moral** ; reproduction et rémunération des **droits patrimoniaux**."},{"cle":{"type":"nombre","valeur":2055,"tolerance":0},"affichage":"2055","explication":"Les droits patrimoniaux durent la vie de l’auteur + 70 ans : 1985 + 70 = **2055**. Son droit moral, lui, ne s’éteint jamais."}]$ex$::jsonb),
